            if (controlName === "addressStreet")
                solicitudBody["address"] =
                    this.sponsorForm.controls[controlName].value;
            else if (controlName === "phone")
                solicitudBody["companyPhone"] =
                    this.sponsorForm.controls[controlName].value;
            else
                solicitudBody[controlName] =
                    this.sponsorForm.controls[controlName].value;
            return solicitudBody;
